import React, { useState, useMemo } from 'react';
import { Trash2, Plus, Play, Clock, Calendar, Download, ShieldCheck, Globe, Home } from 'lucide-react';

// --- HELPER FUNCTIONS ---
const formatTime = (timeStr) => {
  if (!timeStr) return "";
  const [h, m] = timeStr.split(':').map(Number);
  const suffix = h >= 12 ? 'PM' : 'AM';
  const displayH = h % 12 || 12;
  return `${displayH}:${String(m).padStart(2, '0')} ${suffix}`;
};

const addHours = (time, hours) => {
  const [h, m] = time.split(':').map(Number);
  const totalH = h + hours;
  return `${String(totalH).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
};

const DepartmentCard = ({ dept, onUpdate, onGenerate, globalSchedule = [], allDepartments = [] }) => {
  const [activeTab, setActiveTab] = useState("subjects");
  const [localPreview, setLocalPreview] = useState([]);
  const { subjects, proctors, rooms, name: deptName, code: deptCode, id: deptId } = dept;

  // --- GENERATOR UI STATES ---
  const [examDays, setExamDays] = useState(0); 
  const [examDates, setExamDates] = useState([]);
  const [startTime, setStartTime] = useState("08:00");
  const [selectedYear, setSelectedYear] = useState("1");
  const [sectionCount, setSectionCount] = useState(0); 
  const [proctorSource, setProctorSource] = useState("Department");
  const [roomSource, setRoomSource] = useState("Department");

  // --- INPUT STATES (CRUD) ---
  const [pName, setPName] = useState("");
  const [pDayStart, setPDayStart] = useState("");
  const [pDayEnd, setPDayEnd] = useState("");
  const [pTimeStart, setPTimeStart] = useState("08:00");
  const [pTimeEnd, setPTimeEnd] = useState("17:00");
  const [roomNum, setRoomNum] = useState("");
  const [roomType, setRoomType] = useState("Department");

  // --- POOL AGGREGATORS (GLOBAL LISTS) ---
  const globalProctorPool = useMemo(() => allDepartments.flatMap(d => d.proctors), [allDepartments]);
  const globalRoomPool = useMemo(() => allDepartments.flatMap(d => d.rooms), [allDepartments]);

  const handleExamDayChange = (val) => {
    const num = parseInt(val) || 0;
    setExamDays(num);
    setExamDates(new Array(num).fill(''));
  };

  const exportToExcel = () => {
    if (localPreview.length === 0) return alert("Generate a schedule first!");
    const headers = "Day,Section,Date,Time Range,Room,Proctor,Subjects\n";
    const rows = localPreview.map(row => 
      `${row.day},${row.section},${row.date},"${row.time}",${row.room},${row.proctor},"${row.subs}"`
    ).join("\n");

    const blob = new Blob([headers + rows], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${deptCode}_Year${selectedYear}_Schedule.csv`;
    link.click();
  };

  const handleGenerateClick = () => {
    const yearSubs = subjects[selectedYear] || [];
    if (yearSubs.length === 0) return alert("No subjects found for this year level!");
    if (examDays === 0 || sectionCount === 0) return alert("Set days and section count!");
    if (examDates.some(d => !d)) return alert("Please fill all exam dates!");

    // Distribute subjects across days
    const shuffled = [...yearSubs].sort(() => Math.random() - 0.5);
    const dailySubs = Array.from({ length: examDays }, () => []);
    shuffled.forEach((s, i) => dailySubs[i % examDays].push(s));

    const finalGeneratedData = [];
    const previewData = [];

    for (let d = 0; d < examDays; d++) {
      const dayDate = examDates[d];
      const daySubjects = dailySubs[d];
      const duration = daySubjects.length;
      const endTime = addHours(startTime, duration);

      // --- ROOM RESOLUTION ---
      const isRoomFree = (rNum) => !globalSchedule.some(gs => gs.room === rNum && gs.exam_date === dayDate && (startTime < gs.end_time && endTime > gs.start_time));

      const localRooms = rooms.filter(r => isRoomFree(r.number));
      const otherRooms = globalRoomPool.filter(r => !rooms.find(dr => dr.number === r.number) && isRoomFree(r.number));

      let availableRooms = roomSource === "Department" ? [...localRooms, ...otherRooms] : [...otherRooms, ...localRooms];
      availableRooms.sort((a,b) => a.number.localeCompare(b.number, undefined, {numeric: true}));

      let dayUsedProctors = [];

      for (let s = 0; s < sectionCount; s++) {
        const sectionID = `${deptCode}${selectedYear}${String.fromCharCode(65 + s)}`;

        // 1. Assign Room
        const selectedRoom = availableRooms[s];
        if (!selectedRoom) return alert(`No rooms available for ${sectionID} on Day ${d+1}`);

        // 2. Assign Proctor (Strict Shift Enforcement + Fallback)
        const checkProctor = (pool) => pool.find(p => 
            dayDate >= p.dayStart && dayDate <= p.dayEnd &&
            startTime >= p.timeStart && endTime <= p.timeEnd &&
            !dayUsedProctors.includes(p.name) &&
            !globalSchedule.some(gs => gs.proctor === p.name && gs.exam_date === dayDate && (startTime < gs.end_time && endTime > gs.start_time))
        );

        let selectedProctor = checkProctor(proctorSource === "Department" ? proctors : globalProctorPool);
        if (!selectedProctor && proctorSource === "Department") selectedProctor = checkProctor(globalProctorPool);

        if (!selectedProctor) return alert(`No proctor available for ${sectionID} during ${startTime}-${endTime} on Day ${d+1}`);
        dayUsedProctors.push(selectedProctor.name);

        // 3. Output logic
        previewData.push({
          day: d + 1, section: sectionID, date: dayDate,
          time: `${formatTime(startTime)} - ${formatTime(endTime)}`,
          room: selectedRoom.number, proctor: selectedProctor.name,
          subs: daySubjects.map(sub => sub.code).join(", ")
        });

        daySubjects.forEach((sub, idx) => {
          finalGeneratedData.push({
            subject_code: sub.code, subject_name: sub.name, section: sectionID,
            year_level: selectedYear, dept_code: deptCode, exam_date: dayDate,
            start_time: addHours(startTime, idx), end_time: addHours(startTime, idx + 1),
            room: selectedRoom.number, proctor: selectedProctor.name
          });
        });
      }
    }

    setLocalPreview(previewData);
    onGenerate(finalGeneratedData, examDates);
    setActiveTab("preview");
  };

  return (
    <div className="bg-white rounded-[3rem] shadow-2xl border border-slate-200 overflow-hidden mb-12">
      {/* Header */}
      <div className="bg-slate-900 p-8 text-white flex justify-between items-center border-b-4 border-blue-600">
        <h2 className="text-3xl font-black uppercase italic">{deptName}</h2>
        <div className="flex gap-2">
            <span className="bg-blue-600 px-3 py-1 rounded-full text-[9px] font-black uppercase">Local: {proctors.length}</span>
            <span className="bg-slate-700 px-3 py-1 rounded-full text-[9px] font-black uppercase">Global Pool: {globalProctorPool.length}</span>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex bg-slate-50 p-2 border-b">
        {['subjects', 'proctors', 'rooms', 'generate', 'preview'].map(t => (
          <button key={t} onClick={() => setActiveTab(t)} className={`flex-1 py-4 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === t ? 'bg-white shadow-lg text-blue-600' : 'text-slate-400'}`}>
            {t}
          </button>
        ))}
      </div>

      <div className="p-10">
        {/* Generate Tab */}
        {activeTab === 'generate' && (
          <div className="bg-slate-900 rounded-[3rem] p-12 text-white space-y-10">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
              <div className="space-y-6">
                <h4 className="text-blue-400 font-black text-[10px] uppercase tracking-widest flex items-center gap-2"><Calendar size={14}/> Exam Configuration</h4>
                <input type="number" value={examDays || ''} onChange={e => handleExamDayChange(e.target.value)} placeholder="How many exam days?" className="w-full bg-slate-800 p-4 rounded-2xl text-xl font-black text-blue-400 border-none" />
                <div className="space-y-2 max-h-40 overflow-y-auto">
                    {examDates.map((d, i) => (
                      <div key={i} className="flex items-center gap-3 bg-slate-800 p-3 rounded-xl border border-slate-700">
                        <span className="text-blue-500 font-black text-[10px]">DAY {i+1}</span>
                        <input type="date" value={d} onChange={e => { const updated = [...examDates]; updated[i] = e.target.value; setExamDates(updated); }} className="w-full bg-transparent text-xs font-bold outline-none" />
                      </div>
                    ))}
                </div>
                <label className="text-[10px] text-slate-500 uppercase font-black">Universal Start Time</label>
                <input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full bg-slate-800 p-4 rounded-2xl font-black text-blue-400 border-none" />
              </div>

              <div className="space-y-6">
                <h4 className="text-emerald-400 font-black text-[10px] uppercase tracking-widest flex items-center gap-2"><ShieldCheck size={14}/> Allocation Rules</h4>
                <div className="grid grid-cols-2 gap-4">
                    <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)} className="w-full bg-slate-800 p-4 rounded-2xl font-black text-xs text-blue-400 border-none outline-none">
                        {[1, 2, 3, 4, 5].map(y => <option key={y} value={y}>Year {y}</option>)}
                    </select>
                    <input type="number" value={sectionCount || ''} onChange={e => setSectionCount(parseInt(e.target.value) || 0)} placeholder="Total Sections" className="w-full bg-slate-800 p-4 rounded-2xl font-black text-emerald-400 border-none" />
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => setProctorSource(proctorSource === "Department" ? "Global" : "Department")} className="bg-slate-800 p-4 rounded-xl text-[10px] font-black uppercase flex items-center justify-center gap-2 border border-slate-700">
                        {proctorSource === "Department" ? <Home size={14}/> : <Globe size={14}/>} {proctorSource} Proctors
                    </button>
                    <button onClick={() => setRoomSource(roomSource === "Department" ? "Global" : "Department")} className="bg-slate-800 p-4 rounded-xl text-[10px] font-black uppercase flex items-center justify-center gap-2 border border-slate-700">
                         {roomSource === "Department" ? <Home size={14}/> : <Globe size={14}/>} {roomSource} Rooms
                    </button>
                </div>
                <button onClick={handleGenerateClick} className="w-full bg-blue-600 py-8 rounded-[2rem] font-black uppercase tracking-[0.3em] flex items-center justify-center gap-4 hover:bg-blue-500 transition-all shadow-2xl active:scale-95">
                  <Play size={24} fill="currentColor" /> Generate Blocks
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Preview Tab */}
        {activeTab === 'preview' && (
          <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex justify-between items-center">
              <h3 className="text-xl font-black uppercase text-slate-800">Master Preview: Year {selectedYear}</h3>
              <button onClick={exportToExcel} className="flex items-center gap-2 bg-emerald-600 text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase shadow-lg hover:bg-emerald-700">
                <Download size={16} /> Download CSV
              </button>
            </div>
            <div className="border-2 border-slate-100 rounded-[2.5rem] overflow-hidden shadow-sm">
              <table className="w-full text-left">
                <thead className="bg-slate-900 text-white text-[10px] font-black uppercase">
                  <tr>
                    <th className="p-6">Day</th><th className="p-6">Section</th><th className="p-6">Time Window</th><th className="p-6">Room</th><th className="p-6">Staff</th><th className="p-6">Subjects</th>
                  </tr>
                </thead>
                <tbody className="text-xs font-bold text-slate-600">
                  {localPreview.map((row, i) => (
                    <tr key={i} className="border-b hover:bg-blue-50/50 transition-colors">
                      <td className="p-6 text-slate-400">{row.day}</td>
                      <td className="p-6 text-blue-600 font-black">{row.section}</td>
                      <td className="p-6">{row.time}</td>
                      <td className="p-6 font-black">{row.room}</td>
                      <td className="p-6 uppercase text-slate-500">{row.proctor}</td>
                      <td className="p-6 text-[9px] uppercase italic text-slate-400">{row.subs}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Subjects Tab */}
        {activeTab === 'subjects' && (
          <div className="space-y-4">
            <div className="grid grid-cols-4 gap-4 bg-slate-50 p-6 rounded-[2rem]">
              <select className="p-3 rounded-xl text-xs font-bold bg-white outline-none" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
                {[1, 2, 3, 4, 5].map(y => <option key={y} value={y}>Year {y}</option>)}
              </select>
              <input id={`sC-${deptId}`} placeholder="CODE" className="p-3 rounded-xl text-xs font-bold border-none shadow-inner" />
              <input id={`sN-${deptId}`} placeholder="NAME" className="p-3 rounded-xl text-xs font-bold border-none shadow-inner" />
              <button onClick={() => {
                const c = document.getElementById(`sC-${deptId}`).value;
                const n = document.getElementById(`sN-${deptId}`).value;
                if (c && n) {
                  onUpdate('subjects', { ...subjects, [selectedYear]: [...(subjects[selectedYear] || []), { code: c.toUpperCase(), name: n }] });
                  document.getElementById(`sC-${deptId}`).value = '';
                  document.getElementById(`sN-${deptId}`).value = '';
                }
              }} className="bg-blue-600 text-white rounded-xl font-black uppercase text-[10px]">Add Item</button>
            </div>
            <div className="grid grid-cols-2 gap-4">
              {subjects[selectedYear]?.map((s, i) => (
                <div key={i} className="flex justify-between p-5 bg-white border-2 border-slate-50 rounded-2xl items-center font-black text-xs">
                  <span className="text-blue-600">{s.code}</span> <span className="text-slate-400 ml-2">{s.name}</span>
                  <button onClick={() => onUpdate('subjects', { ...subjects, [selectedYear]: subjects[selectedYear].filter((_, idx) => idx !== i) })}><Trash2 size={16} className="text-slate-200 hover:text-rose-500" /></button>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Proctors Tab */}
        {activeTab === 'proctors' && (
          <div className="space-y-8">
            <div className="bg-emerald-50 p-8 rounded-[2.5rem] border border-emerald-100 space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <input value={pName} onChange={e => setPName(e.target.value)} placeholder="INSTRUCTOR FULL NAME" className="p-4 rounded-2xl text-xs font-bold border-none" />
                <button onClick={() => {
                  if (pName && pDayStart && pDayEnd && pTimeStart && pTimeEnd) {
                    onUpdate('proctors', [...proctors, { id: Date.now(), name: pName.toUpperCase(), dayStart: pDayStart, dayEnd: pDayEnd, timeStart: pTimeStart, timeEnd: pTimeEnd }]);
                    setPName("");
                  }
                }} className="bg-emerald-600 text-white rounded-2xl font-black text-[10px] uppercase">Add to Department List</button>
              </div>
              <div className="grid grid-cols-4 gap-4">
                <div className="space-y-1"><label className="text-[9px] font-black uppercase text-emerald-600">Start Date</label><input type="date" value={pDayStart} onChange={e => setPDayStart(e.target.value)} className="w-full p-2 rounded-lg text-[10px]" /></div>
                <div className="space-y-1"><label className="text-[9px] font-black uppercase text-emerald-600">End Date</label><input type="date" value={pDayEnd} onChange={e => setPDayEnd(e.target.value)} className="w-full p-2 rounded-lg text-[10px]" /></div>
                <div className="space-y-1"><label className="text-[9px] font-black uppercase text-emerald-600">Time From</label><input type="time" value={pTimeStart} onChange={e => setPTimeStart(e.target.value)} className="w-full p-2 rounded-lg text-[10px]" /></div>
                <div className="space-y-1"><label className="text-[9px] font-black uppercase text-emerald-600">Time To</label><input type="time" value={pTimeEnd} onChange={e => setPTimeEnd(e.target.value)} className="w-full p-2 rounded-lg text-[10px]" /></div>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              {proctors.map(p => (
                <div key={p.id} className="p-5 border-2 border-slate-50 rounded-[2rem] flex justify-between items-center bg-white">
                  <div>
                    <p className="font-black text-xs uppercase text-slate-800">{p.name}</p>
                    <p className="text-[9px] text-slate-400 font-bold">{p.dayStart} to {p.dayEnd} | {formatTime(p.timeStart)} - {formatTime(p.timeEnd)}</p>
                  </div>
                  <Trash2 size={16} className="text-slate-200 hover:text-rose-500 cursor-pointer" onClick={() => onUpdate('proctors', proctors.filter(item => item.id !== p.id))} />
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Rooms Tab */}
        {activeTab === 'rooms' && (
          <div className="space-y-8">
            <div className="flex gap-4 bg-amber-50 p-6 rounded-[2rem] border border-amber-100">
              <input value={roomNum} onChange={e => setRoomNum(e.target.value)} placeholder="ROOM #" className="flex-1 p-4 rounded-2xl text-sm font-black border-none" />
              <select value={roomType} onChange={e => setRoomType(e.target.value)} className="bg-white px-6 rounded-2xl font-bold text-[10px] uppercase outline-none">
                <option value="Department">Department</option>
                <option value="Global">Global Pool</option>
              </select>
              <button onClick={() => { if (roomNum) { onUpdate('rooms', [...rooms, { id: Date.now(), number: roomNum.toUpperCase(), type: roomType }]); setRoomNum(""); } }} className="bg-amber-600 text-white px-8 rounded-2xl font-black uppercase text-[10px]">Add Room</button>
            </div>
            <div className="grid grid-cols-4 md:grid-cols-6 gap-4">
              {rooms.map(r => (
                <div key={r.id} className="p-6 bg-white border-2 border-slate-50 rounded-[2.5rem] text-center relative group shadow-sm">
                  <span className="font-black text-xl text-slate-800">{r.number}</span>
                  <span className="block text-[8px] font-black text-amber-500 uppercase mt-1">{r.type}</span>
                  <button className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 text-rose-500 transition-opacity" onClick={() => onUpdate('rooms', rooms.filter(item => item.id !== r.id))}><Trash2 size={14}/></button>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DepartmentCard;
